R=Path('/assets');D=R/'assets/third_party/office/grab3d_laptop';g=json.loads((D/'geometry.json').read_text());pivot=np.array(g['pivot_m']);q=math.radians(110);limit=math.radians(140);folder=str(D.relative_to(R));vec=lambda v:' '.join(map(str,np.asarray(v).ravel()))
