 name=p['name'];points=np.array(p['points']);region=points[points[:,1]<-.01] if name=='lid' else points;lo=region.min(0);hi=region.max(0);size=hi-lo;center=(lo+hi)/2
 # The base proxy ends at the keyboard deck; the hinge barrel is not a collision surface.
 mass=p['mass_kg'];inertia=mass/12*np.array([size[1]**2+size[2]**2,size[0]**2+size[2]**2,size[0]**2+size[1]**2]);p['collision']=dict(center=center.tolist(),size=size.tolist());p['inertia_diag']=inertia.tolist()
 E.SubElement(b,'inertial',pos=vec(center),mass=str(mass),diaginertia=vec(inertia));E.SubElement(a,'mesh',name=name,file=name+'.obj');E.SubElement(a,'texture',name=name,type='2d',file=name+'.png');E.SubElement(a,'material',name=name,texture=name,specular='.2',shininess='.2');E.SubElement(b,'geom',name=name+'_visual',type='mesh',mesh=name,material=name,mass='0',contype='0',conaffinity='0');E.SubElement(b,'geom',name=name+'_collision',type='box',size=vec(size/2),pos=vec(center),mass='0',group='3',rgba='0 0 0 0',friction='.7 .005 .0001',solref='.004 1',solimp='.99 .999 .0001',margin='.0001')
 link=E.SubElement(urdf,'link',name=name);inert=E.SubElement(link,'inertial');E.SubElement(inert,'origin',xyz=vec(center));E.SubElement(inert,'mass',value=str(mass));E.SubElement(inert,'inertia',ixx=str(inertia[0]),iyy=str(inertia[1]),izz=str(inertia[2]),ixy='0',ixz='0',iyz='0');vis=E.SubElement(link,'visual');E.SubElement(E.SubElement(vis,'geometry'),'mesh',filename=name+'.obj');col=E.SubElement(link,'collision');E.SubElement(col,'origin',xyz=vec(center));E.SubElement(E.SubElement(col,'geometry'),'box',size=vec(size))
 path='/Laptop/'+name;body=UsdGeom.Xform.Define(s,path);body.AddTranslateOp().Set(Gf.Vec3d(*(pivot if name=='lid' else [0,0,0])));
